<style>
.workforce{max-width:1200px;margin:auto;padding:24px;font:14px/1.7 'Hiragino Kaku Gothic ProN','Yu Gothic',sans-serif;color:#203e42}.workforce h1{font-size:26px;font-weight:700}.workforce h2{font-size:19px;font-weight:700;margin-bottom:12px}.workforce section{background:white;border:1px solid #dce8e9;border-radius:12px;padding:20px;margin:20px 0}.workforce label{display:flex;flex-direction:column;gap:5px;font-weight:600;min-width:0}.workforce input,.workforce select,.workforce textarea{border:1px solid #b5ccce;border-radius:6px;padding:8px;min-height:44px;max-width:100%;background:white;color:#203e42}.workforce select[multiple]{min-height:120px}.workforce button,.workforce .button{background:#00818c;color:white;padding:10px 18px;border-radius:6px;min-height:44px;cursor:pointer;display:inline-block}.workforce a{color:#007581;text-decoration:underline}.workforce .grid-form{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:12px;align-items:end}.workforce .wide{grid-column:1/-1}.workforce .notice{padding:12px;background:#e3f5ed}.workforce .error{padding:12px;background:#fff0ed;color:#a52b18}.workforce .muted{color:#5e7376;font-size:12px}.workforce .scroll{overflow-x:auto}.workforce table{border-collapse:collapse;width:100%;font-size:13px;white-space:nowrap}.workforce td,.workforce th{padding:8px;border:1px solid #dce8e9;text-align:left}.workforce th{background:#eef8f8}.workforce details{border-top:1px solid #dce8e9;padding:12px 0}.workforce summary{cursor:pointer;font-weight:600}.workforce nav{display:flex;flex-wrap:wrap;gap:16px}.workforce textarea{width:100%}.workforce .inline{display:flex;flex-wrap:wrap;gap:10px;align-items:end}.workforce .entry{padding:12px 0;border-bottom:1px solid #dce8e9}.workforce pre{white-space:pre-wrap;overflow-wrap:anywhere;font:inherit}.workforce :focus-visible{outline:2px solid #007581;outline-offset:3px}@media(max-width:600px){.workforce{padding:12px}.workforce section{padding:14px}.workforce .grid-form{grid-templa